#ifndef PSX_RASTER_H
#define PSX_RASTER_H
#include "gp0.h"
/* The VRAM rasteriser also supplies textures generated by offscreen DRAWENVs. */
extern const Gp0Backend psx_softgpu;
/* Rasterise geometry into the GX destination shadow, sampling textures from
 * PSX VRAM. Known pixels permit exact subsequent sprite compositing. */
void psx_softgpu_shadow_poly(const Gp0Mode *, const Gp0Vtx *, int,
                            unsigned short *, unsigned char *, int, int, int, int);
/* Restrict traversal without moving the original fixed-point interpolation
 * origin. Drawing-area clipping alone would introduce different rounding. */
void psx_softgpu_shadow_poly_region(const Gp0Mode *, const Gp0Vtx *, int,
                                   unsigned short *, unsigned char *, int, int, int, int,
                                   int, int, int, int);
void psx_softgpu_shadow_rect(const Gp0Mode *, const Gp0Vtx *, int, int,
                            unsigned short *, unsigned char *, int, int, int, int);
/* While plane is non-NULL, each pixel a primitive writes sets its bit (1024x512 bit plane, VRAM coordinates). */
void psx_softgpu_set_marks(unsigned char *plane, unsigned bit);
#endif
